#!/usr/bin/env node
// Copies the runtime third-party files into public/ (no CDN at runtime, CONTRACTS §11.4):
//   Preact + hooks + htm (ESM), Inter woff2 400/500/600 (latin + latin-ext), a Phosphor SVG sprite of
//   the icons in scripts/icons.txt, push-core's app icons, and every license.
// Inputs are the exact versions pinned in package-lock.json, so `npm ci && npm run vendor` is
// reproducible. `--check` rebuilds in memory and exits 1 if public/ differs (used by the tests).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const NM = path.join(ROOT, 'node_modules');
const PUB = path.join(ROOT, 'public');
const PUSH_ICONS = path.resolve(ROOT, '../../push-core/public/icons');

const read = (p) => fs.readFileSync(p);
const readText = (p) => fs.readFileSync(p, 'utf8');
const version = (pkg) => JSON.parse(readText(path.join(NM, pkg, 'package.json'))).version;

export function buildVendorFiles() {
  const out = new Map(); // relative path in public/ -> Buffer|string

  // --- Preact + hooks + htm --------------------------------------------------------------
  const pv = version('preact');
  const hv = version('htm');
  out.set('vendor/preact.mjs', `/* preact ${pv} (MIT), see LICENSE-preact.txt */\n${readText(path.join(NM, 'preact/dist/preact.mjs')).replace(/\n\/\/# sourceMappingURL=.*$/m, '')}\n`);
  const hooks = readText(path.join(NM, 'preact/hooks/dist/hooks.mjs')).replace(/\n\/\/# sourceMappingURL=.*$/m, '');
  if (!hooks.includes('from"preact"')) throw new Error('preact/hooks no longer imports from "preact"; update vendor.mjs');
  out.set('vendor/hooks.mjs', `/* preact/hooks ${pv} (MIT), see LICENSE-preact.txt */\n${hooks.replaceAll('from"preact"', 'from"./preact.mjs"')}\n`);
  out.set('vendor/htm.mjs', `/* htm ${hv} (Apache-2.0), see LICENSE-htm.txt */\n${readText(path.join(NM, 'htm/dist/htm.mjs')).replace(/\n\/\/# sourceMappingURL=.*$/m, '')}\n`);
  out.set('vendor/LICENSE-preact.txt', read(path.join(NM, 'preact/LICENSE')));
  out.set('vendor/LICENSE-htm.txt', read(path.join(NM, 'htm/LICENSE')));

  // --- Inter ----------------------------------------------------------------------------
  const iv = version('@fontsource/inter');
  const faces = [];
  for (const subset of ['latin-ext', 'latin']) {
    for (const weight of [400, 500, 600]) {
      const file = `inter-${subset}-${weight}-normal.woff2`;
      out.set(`fonts/${file}`, read(path.join(NM, '@fontsource/inter/files', file)));
      const css = readText(path.join(NM, `@fontsource/inter/${weight}.css`));
      const block = css.split('@font-face').find((b) => b.includes(`inter-${subset}-${weight}-normal.woff2`));
      const range = /unicode-range:\s*([^;]+);/.exec(block || '')?.[1];
      if (!range) throw new Error(`no unicode-range for ${file}`);
      faces.push(
        `@font-face {\n  font-family: 'Inter';\n  font-style: normal;\n  font-display: swap;\n  font-weight: ${weight};\n` +
          `  src: url(/fonts/${file}) format('woff2');\n  unicode-range: ${range.trim()};\n}\n`,
      );
    }
  }
  out.set('css/fonts.css', `/* Inter ${iv} from @fontsource/inter (SIL OFL 1.1, see /fonts/LICENSE-inter.txt). Generated by scripts/vendor.mjs. */\n${faces.join('\n')}`);
  out.set('fonts/LICENSE-inter.txt', read(path.join(NM, '@fontsource/inter/LICENSE')));

  // --- Phosphor sprite -----------------------------------------------------------------------
  const phv = version('@phosphor-icons/core');
  const names = readText(path.join(ROOT, 'scripts/icons.txt'))
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'));
  const symbols = names.map((name) => {
    const fill = name.endsWith('-fill');
    const file = path.join(NM, '@phosphor-icons/core/assets', fill ? 'fill' : 'regular', `${name}.svg`);
    const svg = readText(file);
    const viewBox = /viewBox="([^"]+)"/.exec(svg)?.[1] || '0 0 256 256';
    const inner = svg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
    return `<symbol id="${name}" viewBox="${viewBox}">${inner}</symbol>`;
  });
  out.set(
    'icons/phosphor.svg',
    `<svg xmlns="http://www.w3.org/2000/svg"><!-- Phosphor Icons ${phv} (MIT, see LICENSE-phosphor.txt). Generated by scripts/vendor.mjs. -->\n${symbols.join('\n')}\n</svg>\n`,
  );
  out.set('icons/LICENSE-phosphor.txt', read(path.join(NM, '@phosphor-icons/core/LICENSE')));
  out.set(
    'js/icons.js',
    `// Generated by scripts/vendor.mjs from scripts/icons.txt. The ids in /icons/phosphor.svg.\nexport const ICONS = new Set(${JSON.stringify(names)});\n`,
  );

  // --- App icons (from push-core, kept once it's retired) -------------------------------------
  for (const f of ['icon-192.png', 'icon-512.png', 'apple-touch-icon.png', 'badge-96.png', 'icon.svg']) {
    const src = path.join(PUSH_ICONS, f);
    const dest = path.join(PUB, 'icons', f);
    if (fs.existsSync(src)) out.set(`icons/${f}`, read(src));
    else if (fs.existsSync(dest)) out.set(`icons/${f}`, read(dest));
    else throw new Error(`app icon ${f} is missing (push-core's copy is gone and public/ has none)`);
  }
  return out;
}

function main() {
  const check = process.argv.includes('--check');
  const files = buildVendorFiles();
  const stale = [];
  for (const [rel, content] of files) {
    const dest = path.join(PUB, rel);
    const buf = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8');
    const same = fs.existsSync(dest) && fs.readFileSync(dest).equals(buf);
    if (same) continue;
    if (check) stale.push(rel);
    else {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, buf);
      console.log(`wrote public/${rel}`);
    }
  }
  if (check && stale.length) {
    console.error(`vendored files are out of date: ${stale.join(', ')}\nrun: npm ci && npm run vendor`);
    process.exit(1);
  }
  if (!check) console.log(`vendor: ${files.size} files up to date`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) main();
